import sys

def solve(L, C, black):
    # Celulas candidatas: casas vazias com pelo menos um vizinho ortogonal preto
    cand = []
    for x in range(1, L + 1):
        for y in range(1, C + 1):
            if (x, y) in black:
                continue
            if ((x + 1, y) in black or (x - 1, y) in black or
                    (x, y + 1) in black or (x, y - 1) in black):
                cand.append((x, y))

    pos = {cell: i for i, cell in enumerate(cand)}
    n = len(cand)

    # O grafo de conflito entre candidatas e o subgrafo induzido da grade,
    # que e bipartido (coloracao de xadrez pela paridade de x+y).
    # Maximo de pecas brancas = Conjunto Independente Maximo = n - emparelhamento maximo (Konig).
    adj = [[] for _ in range(n)]
    for i, (x, y) in enumerate(cand):
        if (x + y) % 2 == 1:  # lado esquerdo da biparticao
            for nb in ((x, y - 1), (x, y + 1), (x - 1, y), (x + 1, y)):
                j = pos.get(nb)
                if j is not None:
                    adj[i].append(j)

    matchR = [-1] * n

    def try_kuhn(v, visited):
        for u in adj[v]:
            if not visited[u]:
                visited[u] = True
                if matchR[u] == -1 or try_kuhn(matchR[u], visited):
                    matchR[u] = v
                    return True
        return False

    matching = 0
    for i, (x, y) in enumerate(cand):
        if (x + y) % 2 == 1:
            visited = [False] * n
            if try_kuhn(i, visited):
                matching += 1

    return n - matching


def main():
    sys.setrecursionlimit(1 << 20)
    data = sys.stdin.buffer.read().split()
